insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort) values
  ('ARC-075', 'Cuádriceps', 'Sentadilla hack', 'Cuádriceps, glúteo', 'Máquina', 'Con la espalda apoyada en el respaldo inclinado y los hombros bajo las almohadillas, bajas doblando las rodillas y vuelves a subir empujando la plataforma.', 'Pies a la anchura de la cadera y espalda pegada al respaldo todo el recorrido. Baja hasta donde no se te despegue la zona lumbar.', '', '', '', 75),
  ('ARC-076', 'Cuádriceps', 'Sentadilla péndulo', 'Cuádriceps, glúteo', 'Máquina', 'En la máquina de péndulo, con los hombros bajo las almohadillas, bajas en arco doblando las rodillas y subes empujando con toda la planta del pie.', 'Deja que las rodillas avancen por delante de los pies, que es lo que la hace tan buena para cuádriceps. Baja controlando, sin rebotar abajo.', '', '', '', 76),
  ('ARC-077', 'Abdomen', 'Plancha arriba-abajo', 'Core, hombro, tríceps', 'Peso corporal', 'Desde plancha sobre los antebrazos, subes apoyando una mano y luego la otra hasta plancha alta, y bajas otra vez a los codos.', 'Que la cadera no se balancee de lado a lado: separa un poco los pies y aprieta glúteo. Alterna el brazo con el que empiezas.', '', '', '', 77)
